css:
@import url('https://fonts.googleapis.com/css2?family=Century+Gothic&display=swap');

.print-format {
    font-family: 'Century Gothic' !important;
}

.border {
    border: 1px solid black;
}

.border3 {
    border: 1px solid black;
    border-top: none !important;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    font-size: 12px;
    border: 1px solid #000;
    text-align: left;
    line-height: 1em;
    padding: 1px;
    height: 100%;
    display: table-cell;
    vertical-align: middle;
}

.left-align {
    text-align: left;
}

.cell-content {
    text-align: left;
}

.cell-contentt {
    text-align: right;
}

.center {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
}

.center h3 {
    margin: 5px;
}

.three {
    display: flex;
    justify-content: space-between;
    margin: 5px;
}

.three > div:nth-child(2) {
    margin-left: -35px;
}

strong {
    line-height: 0.4rem;
}

.print-on-last-page {
    /*display: none;*/
    page-break-before: always;
}

@media print {
    @page {
        margin: 10mm;
    }

    .print-on-last-page:last-child {
        display: block;

    }
}
